={{ (() => {
const cfg = $('Configuration').first().json;
const url = $('Group Places by URL').item.json.url;
const code = $json.statusCode;
if ($json.error || !code) {
  const e = typeof $json.error === "string" ? $json.error : JSON.stringify($json.error ?? "");
  const reason = /ENOTFOUND|EAI_AGAIN/.test(e) ? "Domain not found" : /ETIMEDOUT|ECONNABORTED|timeout/i.test(e) ? "Timed out" : /ECONNREFUSED/.test(e) ? "Connection refused" : /ECONNRESET|socket hang up/i.test(e) ? "Connection reset" : /CERT|SSL|self.signed/i.test(e) ? "SSL certificate error" : "Unreachable";
  return { severity: "broken", reason: reason };
}
const labels = { 400: "Bad request", 401: "Unauthorized", 403: "Forbidden", 404: "Not found", 410: "Gone", 429: "Too many requests", 500: "Server error", 502: "Bad gateway", 503: "Service unavailable", 504: "Gateway timeout", 999: "Blocked" };
const label = (code + " " + (labels[code] || (code >= 500 ? "Server error" : ""))).trim();
if ([401, 403, 429, 503, 999].includes(code)) return { severity: "verify", reason: label };
if (code >= 400) return { severity: "broken", reason: label };
const body = String($json.body ?? $json.data ?? "").slice(0, 500000);
const clean = s => s.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim().toLowerCase();
const headings = (body.match(/<(title|h1|h2)[^>]*>[\s\S]*?<\/(title|h1|h2)>/gi) || []).map(clean);
const phrases = String(cfg.softErrorPhrases || "").split(",").map(p => p.trim().toLowerCase()).filter(Boolean);
const hit = headings.map(h => phrases.find(p => h.includes(p))).find(Boolean);
if (hit) return { severity: "broken", reason: "Soft 404: page says “" + hit + "”" };
const path = u => u.replace(/^(https?:)?\/\/[^\/]+/i, "").replace(/[?#].*$/, "").replace(/\/+$/, "");
const canonicalTag = (body.match(/<link[^>]+rel=["']canonical["'][^>]*>/i) || [""])[0];
const canonical = (canonicalTag.match(/href=["']([^"']+)["']/i) || [])[1];
if (canonical && path(url) !== "" && path(canonical) === "") return { severity: "broken", reason: "Redirects to the homepage" };
return { severity: "ok", reason: label };
})() }}

