={{ (() => {
const esc = s => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/'/g, "&#39;");
const isFresh = i => i.isNew && !(i.knownStatus === "verify" && i.check.severity === "verify");
const issues = $json.issues.slice().sort((a, b) => (a.check.severity === "broken" ? 0 : 1) - (b.check.severity === "broken" ? 0 : 1) || (isFresh(a) ? 0 : 1) - (isFresh(b) ? 0 : 1));
const broken = issues.filter(i => i.check.severity === "broken").length;
const fresh = issues.filter(isFresh).length;
const freshBroken = issues.filter(i => i.check.severity === "broken" && isFresh(i)).length;
const callout = broken === 0 ? "" : "<div style='margin:0 0 16px;padding:12px 16px;border-radius:6px;background:#E6F1FB;color:#0C3B66;font-size:14px;line-height:1.5;'><strong>Fix these links from Slack.</strong> " + (freshBroken > 0 ? "Each new broken link was just sent to your Slack channel. Click <strong>Fix this link</strong>, then paste the new URL to replace it in every description and comment where it appears." : "Their fix requests were sent to your Slack channel in earlier weeks. Answer them there to replace the links.") + "</div>";
const pill = (text, bg, fg) => "<span style='display:inline-block;padding:2px 8px;border-radius:4px;background:" + bg + ";color:" + fg + ";font-size:12px;font-weight:bold;'>" + text + "</span> ";
const rows = issues.map(i => "<tr><td style='padding:16px 0;border-top:1px solid #E5E5E5;'>" + (i.check.severity === "broken" ? pill("Broken", "#FCEBEB", "#A32D2D") : pill("To verify", "#FAEEDA", "#854F0B")) + (isFresh(i) ? pill("New", "#E6F1FB", "#185FA5") : "") + "<span style='color:#666666;font-size:13px;'>" + esc(i.check.reason) + "</span><div style='margin:8px 0;word-break:break-all;'><a href='" + esc(i.url) + "' style='color:#185FA5;'>" + esc(i.url) + "</a></div><div style='font-size:13px;color:#666666;'>Found in " + i.occurrences.length + (i.occurrences.length === 1 ? " place:" : " places:") + "</div><ul style='margin:4px 0 0;padding-left:18px;'>" + i.occurrences.map(o => "<li style='margin:2px 0;'>" + (o.type === "comment" ? "Your comment on " : "Description of ") + "<a href='" + esc(o.placeUrl) + "' style='color:#185FA5;'>" + esc(o.title) + "</a></li>").join("") + "</ul>" + (i.check.severity === "broken" && isFresh(i) ? "<div style='margin:6px 0 0;font-size:12px;color:#888888;'>Fix request sent to Slack</div>" : "") + "</td></tr>").join("");
return "<div style='background:#F5F5F5;padding:24px 12px;font-family:Arial,Helvetica,sans-serif;'><table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='max-width:600px;margin:0 auto;background:#FFFFFF;border-radius:8px;'><tr><td style='padding:24px;'><h1 style='margin:0 0 4px;font-size:20px;color:#111111;'>YouTube Link Check</h1><p style='margin:0 0 8px;font-size:14px;color:#666666;'>" + $now.toFormat("d LLL yyyy") + " · " + broken + " broken, " + (issues.length - broken) + " to verify, " + fresh + " new this week</p>" + callout + "<table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='font-size:14px;color:#111111;'>" + rows + "</table><p style='margin:16px 0 0;padding-top:16px;border-top:1px solid #E5E5E5;font-size:12px;color:#888888;line-height:1.5;'>Broken: page missing, server error, unreachable domain, error page or redirect to the homepage. To verify: the site blocked the automated check, so open the link manually.</p></td></tr></table></div>";
})() }}

