={{ (() => {
const { results } = $json;
const total = results.length;
const failed = results.filter(r => r.error).length;
const p = $('Prepare Replacements').first().json;
return failed === 0 ? ":white_check_mark: Replaced <" + p.oldUrl + "> with <" + p.newUrl + "> in " + total + (total === 1 ? " place." : " places.") : ":warning: Replaced <" + p.oldUrl + "> in " + (total - failed) + " of " + total + " places. Check the failed updates in the execution log.";
})() }}

